    const transcribeTracks = profile ? profile.assignments.filter((a) => a.do_transcribe).length : void 0;
    const extractTracks = profile ? profile.assignments.filter((a) => a.do_score || a.do_transcribe).length : _probedInfo.audio_tracks;
